{
  "propositions": [
    {
      "text": "Many Labs Replication Project replicated 13 effects across 36 samples and over 6,000 participants.",
      "exactQuote": "This dataset is from the Many Labs Replication Project in which 13 effects were replicated across 36 samples and over 6,000 participants.",
      "blockId": "c-psych-002#block-5"
    },
    {
      "text": "The dataset includes replication data, demographic variables, and contextual information.",
      "exactQuote": "Data from the replications are included, along with demographic variables about the participants and contextual information about the environment in which the replication was conducted.",
      "blockId": "c-psych-002#block-5"
    },
    {
      "text": "The sample comprised 6,344 participants from 36 sources including university subject pools, Amazon Mechanical Turk, Project Implicit, and other sources.",
      "exactQuote": "Our sample was comprised of 6,344 participants recruited from 36 different sources including university subject pools, Amazon Mechanical Turk, Project Implicit, and other sources.",
      "blockId": "c-psych-002#block-6"
    },
    {
      "text": "The aggregate sample had a mean age of 25.98.",
      "exactQuote": "The aggregate sample had a mean age of 25.98.",
      "blockId": "c-psych-002#block-7"
    },
    {
      "text": "Participant ethnicity was 65.1% White, 6.7% Black or African American, 6.5% East Asian, 4.5% South Asian, 17.2% Other or Unknown.",
      "exactQuote": "Participant ethnicity was: 65.1% White, 6.7% Black or African American, 6.5% East Asian, 4.5% South Asian, 17.2% Other or Unknown.",
      "blockId": "c-psych-002#block-7"
    },
    {
      "text": "Participant gender was 63.6% female, 29.9% male, 6.5% no response.",
      "exactQuote": "Participant gender was 63.6% female, 29.9% male, 6.5% no response.",
      "blockId": "c-psych-002#block-7"
    },
    {
      "text": "The study materials consisted of 13 effects drawn from 12 papers.",
      "exactQuote": "The study materials consisted of 13 effects drawn from 12 papers",
      "blockId": "c-psych-002#block-9"
    },
    {
      "text": "The effects included Sunk costs (Oppenheimer, Meyvis, & Davidenko, 2009).",
      "exactQuote": "Sunk costs (Oppenheimer, Meyvis, & Davidenko, 2009)",
      "blockId": "c-psych-002#block-9"
    },
    {
      "text": "The effects included Gain versus loss framing (Tversky & Kahneman, 1981).",
      "exactQuote": "Gain versus loss framing (Tversky & Kahneman, 1981)",
      "blockId": "c-psych-002#block-9"
    },
    {
      "text": "The effects included Anchoring (Jacowitz & Kahneman, 1995).",
      "exactQuote": "Anchoring (Jacowitz & Kahneman, 1995)",
      "blockId": "c-psych-002#block-9"
    },
    {
      "text": "The effects included Retrospective gambler's fallacy (Oppenheimer & Monin, 2009).",
      "exactQuote": "Retrospective gambler's fallacy (Oppenheimer & Monin, 2009)",
      "blockId": "c-psych-002#block-9"
    },
    {
      "text": "The effects included Low-vs.-high category scales (Schwarz, Hippler, Deutsch, & Strack, 1985).",
      "exactQuote": "Low-vs.-high category scales (Schwarz, Hippler, Deutsch, & Strack, 1985)",
      "blockId": "c-psych-002#block-9"
    },
    {
      "text": "The effects included Norm of reciprocity (Hyman & Sheatsley, 1950).",
      "exactQuote": "Norm of reciprocity (Hyman & Sheatsley, 1950)",
      "blockId": "c-psych-002#block-9"
    },
    {
      "text": "The effects included Allowed/Forbidden (Rugg, 1941).",
      "exactQuote": "Allowed/Forbidden (Rugg, 1941)",
      "blockId": "c-psych-002#block-9"
    },
    {
      "text": "The effects included Quote Attribution (Lorge & Curtis, 1936).",
      "exactQuote": "Quote Attribution (Lorge & Curtis, 1936)",
      "blockId": "c-psych-002#block-9"
    },
    {
      "text": "The effects included Flag Priming (Carter, Ferguson, & Hassin, 2011).",
      "exactQuote": "Flag Priming (Carter, Ferguson, & Hassin, 2011)",
      "blockId": "c-psych-002#block-9"
    },
    {
      "text": "10 of the 13 effects were successfully replicated across the 36 samples.",
      "exactQuote": "10 of the 13 effects were successfully replicated across the 36 samples",
      "blockId": "c-psych-002#block-11"
    },
    {
      "text": "The replication demonstrated that many classic psychological findings are robust when tested with large, diverse samples and standardized protocols.",
      "exactQuote": "demonstrating that many classic psychological findings are robust when tested with large, diverse samples and standardized protocols.",
      "blockId": "c-psych-002#block-11"
    },
    {
      "text": "Data were collected in-lab and online through a standardized procedure administered via an online link.",
      "exactQuote": "Data were collected in-lab and online through a standardized procedure administered via an online link.",
      "blockId": "c-psych-002#block-13"
    },
    {
      "text": "The dataset is stored on the Open Science Framework website.",
      "exactQuote": "The dataset is stored on the Open Science Framework website.",
      "blockId": "c-psych-002#block-13"
    },
    {
      "text": "The dataset is licensed under CC0 1.0 Universal.",
      "exactQuote": "License: CC0 1.0 Universal.",
      "blockId": "c-psych-002#block-13"
    }
  ]
}
